import {drawRoyalPerson} from './castle-art.js';
import {drawTool} from './premium-art.js';
const rect=(c,x,y,w,h,fill,stroke='#726650',r=3)=>{c.beginPath();c.roundRect(x,y,w,h,r);if(fill){c.fillStyle=fill;c.fill();}if(stroke){c.strokeStyle=stroke;c.lineWidth=1.5;c.stroke();}};
// Shared by battlefield, construction and the live inspector preview. Collision bounds never change.
export function drawCastleObject(c,b,m){const p=m.spec(b),r=b.type==='king'?{w:44,h:80}:m.box(b),pos=b.body?.position||b,level=p.level||1,angle=b.body?.angle||((b.rotation||0)*Math.PI/180),king=b.type==='king',person=king||['footman','archer'].includes(b.type);c.save();if(person){drawRoyalPerson(c,{x:pos.x,y:king?pos.y:pos.y+r.h/2,type:king?'king':b.type==='footman'?'footman':'archer',side:1,clock:m.clock,scale:king?.65:.43,walking:b.walking,attack:king?Math.max(0,1-(m.clock-(m.nextShot-p.period))/350):b.type==='footman'?b.attack:Math.max(0,1-((b.cooldown||0)-m.clock)/p.period),hurt:Math.max(0,1-(m.clock-(b.hurtAt??-Infinity))/400),hp:b.hp===undefined?1:b.hp/p.hp});const foot=king?pos.y:pos.y+r.h/2;c.translate(pos.x,foot);const personScale=king?.65:.43;c.scale(personScale,personScale);if(level>=2){rect(c,-10,-51,20,16,'#9babb0','#64767c');}if(level>=3){rect(c,-19,-53,8,11,'#8095a4','#d6bf7f');rect(c,11,-53,8,11,'#8095a4','#d6bf7f');}if(level>=4&&!king){c.fillStyle='#b3484d';c.beginPath();c.moveTo(-4,-89);c.lineTo(-9,-105);c.lineTo(4,-92);c.fill();}if(level>=5){c.strokeStyle='#e8c772';c.lineWidth=2;c.beginPath();c.moveTo(-9,-49);c.lineTo(9,-49);c.moveTo(0,-49);c.lineTo(0,-36);c.stroke();}}else{c.translate(pos.x,pos.y);c.rotate(angle);const weapon=['cannon','catapult','ballista','repair','rune','trap'].includes(b.type);if(weapon){if(['cannon','ballista','catapult'].includes(b.type))drawTool(c,b.type,0,5,.46,{time:m.clock,active:m.clock<(b.cooldown||0)-400});else{rect(c,-16,12,32,6,'#745c45');c.fillStyle=b.type==='rune'?'#7497bd':'#774e3e';c.font='bold 26px serif';c.textAlign='center';c.fillText(b.type==='repair'?'+':b.type==='rune'?'✦':'⇧',0,7);}}else{const wood=b.type==='wood'||b.material==='oak'||['beam','bridge','platform','stairs','roof','barricade'].includes(b.type);rect(c,-p.w/2,-p.h/2,p.w,p.h,wood?'#b08c62':b.material==='iron'?'#88948e':b.material==='crystal'?'#b5c5c8':'#bcb9a3');c.strokeStyle=wood?'#8f6e4e':'#8c9584';c.lineWidth=1.5;for(let y=-p.h/2+13;y<p.h/2;y+=13){c.beginPath();c.moveTo(-p.w/2+2,y);c.lineTo(p.w/2-2,y);c.stroke();if(!wood){c.beginPath();c.moveTo((Math.round(y/13)%2?-.2:.2)*p.w,y);c.lineTo((Math.round(y/13)%2?-.2:.2)*p.w,y+13);c.stroke();}}if(['window','gate','reinforced'].includes(b.type))rect(c,-10,-13,20,31,m.gateOpen?'#b7c7ae':'#52685c','#756a50',8);}
 // Added hardware, braces, studs, framing and heraldry distinguish every tier beyond color.
 if(level>=2){for(const x of [-r.w/2+5,r.w/2-5])rect(c,x-2,-r.h/2+3,4,r.h-6,'#778589','#d4c39b',1);}if(level>=3){c.strokeStyle='#5e7077';c.lineWidth=3;c.beginPath();c.moveTo(-r.w/2+4,-r.h/2+4);c.lineTo(r.w/2-4,r.h/2-4);c.stroke();}if(level>=4){for(const x of [-r.w/2+7,r.w/2-7])for(const y of [-r.h/2+7,r.h/2-7]){c.fillStyle='#e0c37e';c.beginPath();c.arc(x,y,2.5,0,Math.PI*2);c.fill();}}if(level>=5){rect(c,-8,-r.h/2+5,16,17,'#4e6d82','#ead08b',4);c.fillStyle='#ead08b';c.font='bold 12px serif';c.textAlign='center';c.fillText('✦',0,-r.h/2+18);}}
 c.restore();}
